package at.hausgarten.service;

import android.content.Context;
import android.webkit.JavascriptInterface;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.function.*;

/** Private bundled top-document bridge: no paths, URIs, external services or arbitrary tool dispatch. */
final class BrowserMediaBridge {
    private final Context context;private final PixelLocalStore store;private final BooleanSupplier trusted;private final Supplier<String> token;private BrowserMediaFiles currentFiles;private String fileScope="";
    private static final Set<String> ERROR_CODES=new HashSet<>(Arrays.asList("BROWSER_MEDIA_PAGE_REJECTED","BROWSER_MEDIA_INPUT_INVALID","BROWSER_MEDIA_CONTEXT_CHANGED","BROWSER_MEDIA_REQUEST_INVALID","BROWSER_MEDIA_CHUNK_INVALID","BROWSER_MEDIA_SPACE_REQUIRED","BROWSER_MEDIA_PATH_INVALID","BROWSER_MEDIA_STORAGE_UNAVAILABLE","BROWSER_MEDIA_REPLAY_MISMATCH","BROWSER_MEDIA_UPLOAD_INVALID","BROWSER_MEDIA_SIZE_INVALID","BROWSER_MEDIA_MIME_INVALID","BROWSER_MEDIA_UPLOAD_REVIEW_REQUIRED","BROWSER_MEDIA_CHUNK_ORDER_INVALID","BROWSER_MEDIA_UPLOAD_CLOSED","BROWSER_MEDIA_UPLOAD_INCOMPLETE","BROWSER_MEDIA_ORIGINAL_MISSING","BROWSER_MEDIA_ORIGINAL_MISSING_OR_CHANGED","BROWSER_MEDIA_REFERENCE_INVALID","BROWSER_MEDIA_GRAPH_INVALID","BROWSER_MEDIA_GRAPH_SECRET_FIELD","BROWSER_MEDIA_INLINE_MEDIA_FORBIDDEN","BROWSER_MEDIA_INTERRUPTED","BROWSER_MEDIA_WRITE_CONFLICT","BROWSER_MEDIA_RESTORE_REVIEW_REQUIRED","BROWSER_MEDIA_MIRROR_REQUIRED","BROWSER_MEDIA_MIRROR_PENDING","BROWSER_MEDIA_RECORD_INVALID","BROWSER_MEDIA_KEY_INVALID","BROWSER_MEDIA_NOT_REFERENCED","BROWSER_MEDIA_ACCESS_DENIED","BROWSER_MEDIA_ACTIVE_CONFLICT","BROWSER_MEDIA_CONTEXT_CHANGED","BROWSER_MEDIA_CONTEXT_INVALID","BROWSER_MEDIA_DUPLICATE_KEY","BROWSER_MEDIA_GRAPH_INVALID","BROWSER_MEDIA_GRAPH_TOO_LARGE","BROWSER_MEDIA_KEY_INVALID","BROWSER_MEDIA_MIRROR_CLOSED","BROWSER_MEDIA_MIRROR_INCOMPLETE","BROWSER_MEDIA_MIRROR_NOT_ALLOWED","BROWSER_MEDIA_MIRROR_REQUIRED","BROWSER_MEDIA_RECORD_INVALID","BROWSER_MEDIA_RECORD_MISSING","BROWSER_MEDIA_REFERENCE_INVALID","BROWSER_MEDIA_REFERENCE_NOT_ACTIVE","BROWSER_MEDIA_REPLAY_MISMATCH","BROWSER_MEDIA_REQUEST_ID_REQUIRED","BROWSER_MEDIA_RESTORE_MIRROR_REQUIRED","BROWSER_MEDIA_RESTORE_REVIEW_REQUIRED","BROWSER_MEDIA_SELECTION_INVALID","BROWSER_MEDIA_SELECTION_REQUIRED","BROWSER_MEDIA_SOURCE_INVALID","BROWSER_MEDIA_STATE_INVALID","BROWSER_MEDIA_VERSION_UNSUPPORTED","BROWSER_MEDIA_WRITE_CONFLICT","BROWSER_MEDIA_WRITE_PREPARATION_REQUIRED","BROWSER_MEDIA_WRITE_PENDING","BROWSER_MEDIA_WRITE_CANCELLED","BROWSER_MEDIA_WRITE_ALREADY_COMMITTED","BROWSER_MEDIA_OPERATION_FAILED"));
    BrowserMediaBridge(Context context,PixelLocalStore store,BooleanSupplier trusted,Supplier<String> token){this.context=context;this.store=store;this.trusted=trusted;this.token=token;}
    private interface Action {JSONObject run(JSONObject args,JSONObject identity)throws Exception;}
    private String perform(String raw,boolean identityRequired,String[] fields,Action action){try{
        LocalAuthorityGuard.assertStoreMayOpen(context);if(!trusted.getAsBoolean()||raw==null||raw.length()>8*1024*1024)throw rejected("PAGE_REJECTED");JSONObject args=new JSONObject(raw);String expected=token.get(),supplied=args.optString("page_token");if(!(args.opt("page_token") instanceof String)||expected==null||expected.length()<16||supplied.length()>200||!MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8))||!(args.opt("formatVersion") instanceof Number)||!"1".equals(args.opt("formatVersion").toString()))throw rejected("PAGE_REJECTED");
        Set<String> allowed=new HashSet<>(Arrays.asList(fields));allowed.addAll(Arrays.asList("formatVersion","page_token","installation_id","restore_epoch"));for(Iterator<String> keys=args.keys();keys.hasNext();)if(!allowed.contains(keys.next()))throw rejected("INPUT_INVALID");JSONObject identity=new BackupDeviceGuard(context).current();if(identityRequired&&(!identity.getString("installationId").equals(args.optString("installation_id"))||!identity.getString("restoreEpoch").equals(args.optString("restore_epoch"))))throw rejected("CONTEXT_CHANGED");
        return new JSONObject().put("ok",true).put("data",action.run(args,identity)).toString();
    }catch(Exception error){String code=error instanceof JSONException?"BROWSER_MEDIA_INPUT_INVALID":error.getMessage();if(!ERROR_CODES.contains(code))code="BROWSER_MEDIA_OPERATION_FAILED";try{return new JSONObject().put("ok",false).put("error",new JSONObject().put("code",code).put("message",code)).toString();}catch(Exception impossible){return "{\"ok\":false,\"error\":{\"code\":\"BROWSER_MEDIA_OPERATION_FAILED\"}}";}}}
    private BrowserMediaRepository repository()throws Exception {return new BrowserMediaRepository(context,store);}
    private synchronized BrowserMediaFiles files(JSONObject identity)throws Exception {String scope=PixelMcpWriteTools.hash(identity);if(currentFiles==null||!scope.equals(fileScope)){currentFiles=new BrowserMediaFiles(new File(context.getFilesDir(),"browser-media"),new File(context.getNoBackupFilesDir(),"browser-media-upload/"+scope));fileScope=scope;}return currentFiles;}
    private static IOException rejected(String code){return new IOException("BROWSER_MEDIA_"+code);}
    private static String request(JSONObject args)throws Exception {String id=args.getString("request_id");if(!id.matches("[A-Za-z0-9_.:-]{8,200}"))throw rejected("REQUEST_INVALID");return id;}
    private static long integer(JSONObject args,String key)throws Exception {try{if(!(args.opt(key) instanceof Number))throw rejected("INPUT_INVALID");return new java.math.BigDecimal(args.get(key).toString()).longValueExact();}catch(Exception invalid){throw rejected("INPUT_INVALID");}}
    @JavascriptInterface public String mediaStatus(String raw){return perform(raw,false,new String[]{},(a,i)->repository().status());}
    @JavascriptInterface public String beginMediaUpload(String raw){return perform(raw,true,new String[]{"request_id","byte_size","mime_type"},(a,i)->files(i).begin(PixelMcpWriteTools.hash(request(a)),integer(a,"byte_size"),a.getString("mime_type")));}
    @JavascriptInterface public String writeMediaChunk(String raw){return perform(raw,true,new String[]{"upload_id","offset","chunk_base64"},(a,i)->{String encoded=a.getString("chunk_base64");if(encoded.length()>((BrowserMediaFiles.CHUNK_BYTES+2)/3)*4||encoded.length()%4!=0||!encoded.matches("[A-Za-z0-9+/]*={0,2}"))throw rejected("CHUNK_INVALID");byte[] chunk;try{chunk=Base64.getDecoder().decode(encoded);}catch(Exception invalid){throw rejected("CHUNK_INVALID");}return files(i).append(a.getString("upload_id"),integer(a,"offset"),chunk);});}
    @JavascriptInterface public String finishMediaUpload(String raw){return perform(raw,true,new String[]{"upload_id"},(a,i)->files(i).complete(a.getString("upload_id")));}
    @JavascriptInterface public String readMediaChunk(String raw){return perform(raw,true,new String[]{"record_id","reference","offset","length"},(a,i)->{JSONObject ref=a.getJSONObject("reference");repository().assertReadableReference(a.getString("record_id"),ref);long requested=integer(a,"length");if(requested<1||requested>BrowserMediaFiles.CHUNK_BYTES)throw rejected("CHUNK_INVALID");byte[] bytes=files(i).read(ref,integer(a,"offset"),(int)requested);return new JSONObject().put("byte_size",bytes.length).put("chunk_base64",Base64.getEncoder().encodeToString(bytes));});}
    @JavascriptInterface public String readMediaRecord(String raw){return perform(raw,true,new String[]{"key"},(a,i)->repository().readRecord(a.getString("key")));}
    @JavascriptInterface public String writeMediaRecord(String raw){return perform(raw,true,new String[]{"operation","request_id","source","key","mirror","expected_record_hash","reason","record"},(a,i)->{if(!a.has("record")||a.has("mirror")&&!(a.opt("mirror") instanceof Boolean))throw rejected("INPUT_INVALID");JSONObject record=a.isNull("record")?null:a.getJSONObject("record");if(a.optBoolean("mirror")){if(record==null||a.has("operation"))throw rejected("INPUT_INVALID");return repository().writeMirrorRecord(request(a),a.getString("source"),a.getString("key"),record);}String operation=a.getString("operation");if(operation.equals("cleanup_files")){if(record!=null)throw rejected("INPUT_INVALID");request(a);return repository().cleanupFiles();}if(operation.equals("cleanup")){if(record!=null)throw rejected("INPUT_INVALID");return repository().cleanupDeletedKey(a.getString("key"),request(a));}if(operation.equals("prepare")){if(record!=null)throw rejected("INPUT_INVALID");return repository().prepareRecordWrite(request(a),a.getString("key"),a.getString("expected_record_hash"));}if(operation.equals("cancel")){if(record!=null||!Arrays.asList("BUFFER_STORAGE_FAILED","DISCARDED").contains(a.optString("reason")))throw rejected("INPUT_INVALID");return repository().cancelRecordWrite(request(a),a.getString("key"),a.getString("expected_record_hash"),a.getString("reason"));}if(!operation.equals("commit"))throw rejected("INPUT_INVALID");return repository().writeRecord(request(a),a.getString("key"),a.getString("expected_record_hash"),record);});}
    @JavascriptInterface public String beginMediaMirror(String raw){return perform(raw,true,new String[]{"request_id","source"},(a,i)->repository().beginMirror(request(a),a.getString("source")));}
    @JavascriptInterface public String completeMediaMirror(String raw){return perform(raw,true,new String[]{"request_id","source","keys"},(a,i)->repository().completeMirror(request(a),a.getString("source"),a.getJSONArray("keys")));}
}
